1	/****************************************************************************
2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/bk7258_wdt.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * BK7258 (T5-AI) hardware watchdog NuttX lower-half driver — SDK wrapper.
7	 *
8	 * Calls bk_wdt_* / bk_aon_wdt_* SDK APIs.  Zero register access.
9	 *
10	 * Fixes: AON WDT orphaned by bootloader → infinite reboot (F-01).
11	 * The bootloader arms both APB + AON WDTs (~8 s); this driver stops
12	 * AON WDT immediately on init and manages APB WDT via NuttX automonitor.
13	 ****************************************************************************/
