96	static int bk7258_wdt_start(struct watchdog_lowerhalf_s *lower)
97	{
98	  struct bk7258_wdt_lowerhalf_s *priv =
99	    (struct bk7258_wdt_lowerhalf_s *)lower;
100	
101	  if (bk_wdt_start(priv->timeout) != BK_OK)
102	    {
103	      wderr("ERROR: bk_wdt_start failed\n");
104	      return -EIO;
105	    }
106	
107	  priv->started = true;
108	  wdinfo("started, timeout=%" PRIu32 " ms\n", priv->timeout);
109	  return OK;
110	}
111	
112	static int bk7258_wdt_stop(struct watchdog_lowerhalf_s *lower)
113	{
114	  struct bk7258_wdt_lowerhalf_s *priv =
115	    (struct bk7258_wdt_lowerhalf_s *)lower;
116	
117	  bk_wdt_stop();
118	  bk_aon_wdt_stop();  /* Stop AON WDT (fixes F-01 reboot root cause) */
119	
120	  priv->started = false;
121	  wdinfo("stopped\n");
122	  return OK;
123	}
124	
125	static int bk7258_wdt_keepalive(struct watchdog_lowerhalf_s *lower)
126	{
127	  static int marker_printed;
128	
129	  if (marker_printed == 0)
130	    {
131	      marker_printed = 1;
132	      up_putc('K');
133	    }
134	
135	  return (bk_wdt_feed() == BK_OK) ? OK : -EIO;
136	}
137	
138	static int bk7258_wdt_getstatus(struct watchdog_lowerhalf_s *lower,
139	                                struct watchdog_status_s *status)
140	{
141	  struct bk7258_wdt_lowerhalf_s *priv =
142	    (struct bk7258_wdt_lowerhalf_s *)lower;
143	
144	  status->flags = WDFLAGS_RESET;
145	  if (priv->started)
146	    {
147	      status->flags |= WDFLAGS_ACTIVE;
148	    }
149	
150	  status->timeout = priv->timeout;
151	
152	  /* timeleft: we cannot read the current counter from the BK7258 APB WDT
153	   * (no readable counter register).  Return timeout as an upper bound. */
154	
155	  status->timeleft = priv->timeout;
156	  return OK;
157	}
158	
159	static int bk7258_wdt_settimeout(struct watchdog_lowerhalf_s *lower,
160	                                 uint32_t timeout)
161	{
162	  struct bk7258_wdt_lowerhalf_s *priv =
163	    (struct bk7258_wdt_lowerhalf_s *)lower;
164	
165	  if (timeout == 0)
166	    {
167	      return -EINVAL;
168	    }
169	
170	  if (timeout > BK7258_WDT_MAX_TIMEOUT_MS)
171	    {
172	      timeout = BK7258_WDT_MAX_TIMEOUT_MS;
173	    }
174	
175	  priv->timeout = timeout;
176	
177	  /* If already running, re-arm with new period.
178	   * bk_wdt_start() internally does soft_reset + key sequence. */
179	
180	  if (priv->started)
181	    {
182	      bk_wdt_start(priv->timeout);
183	    }
184	
185	  wdinfo("timeout set to %" PRIu32 " ms\n", priv->timeout);
186	  return OK;
187	}
