193	/****************************************************************************
194	 * Name: bk7258_wdt_initialize
195	 *
196	 * Description:
197	 *   Initialize the BK7258 WDT and register as /dev/watchdog0.
198	 *
199	 *   ★ Root cause fix: stops AON WDT immediately.  Bootloader arms both
200	 *   APB + AON WDTs; AON is not managed by NuttX watchdog framework and
201	 *   would expire ~8 s after boot → reboot loop.
202	 *
203	 *   APB WDT is managed by NuttX automonitor (CONFIG_WATCHDOG_AUTOMONITOR):
204	 *   register triggers start + periodic keepalive via work queue.
205	 *
206	 ****************************************************************************/
207	
208	int bk7258_wdt_initialize(void)
209	{
210	  static bool s_inited;
211	  struct bk7258_wdt_lowerhalf_s *priv = &g_bk7258_wdt;
212	  void *handle;
213	  int ret;
214	
215	  if (s_inited)
216	    {
217	      return OK;
218	    }
219	
220	  s_inited = true;
221	
222	  /* Initialize the SDK WDT state, then stop its TIMER_ID2 feeder.  NuttX
223	   * automonitor owns periodic keepalive through bk_wdt_feed(). */
224	
225	  bk_timer_driver_init();
226	
227	  if (!bk_wdt_is_driver_inited())
228	    {
229	      bk_wdt_driver_init();
230	    }
231	
232	  bk_timer_stop(TIMER_ID2);
233	
234	  /* Stop the bootloader's AON WDT before registering the NuttX lower-half.
235	   * AON WDT is not managed by the NuttX watchdog framework. */
236	
237	  bk_aon_wdt_stop();
238	
239	  priv->wdt_lh.ops = &g_bk7258_wdt_ops;
240	  priv->timeout    = BK7258_WDT_DEFAULT_TIMEOUT_MS;
241	  priv->started    = false;
242	
243	  up_putc('A');
244	  handle = watchdog_register("/dev/watchdog0",
245	                             (struct watchdog_lowerhalf_s *)priv);
246	  if (handle == NULL)
247	    {
248	      wderr("ERROR: watchdog_register failed\n");
249	      return -ENOMEM;
250	    }
251	
252	  up_putc('B');
253	
254	  ret = wd_start(&g_bk7258_wdt_probe, 1,
255	                 bk7258_wdt_tick_probe, 0);
256	  up_putc(ret == OK ? 'W' : 'E');
257	
258	  wdinfo("BK7258 WDT registered, default timeout=%" PRIu32 " ms\n",
259	         priv->timeout);
260	  return OK;
261	}
262	
263	#endif /* CONFIG_BK7258_WDT */
