1	/*
2	 * boot_main.c - BK7258 Tier-1 bootloader C main.
3	 *
4	 *   uint32_t c_main(void);
5	 *
6	 * Responsibilities (Tier-1 features I / A, with J handled by start.S):
7	 *   I  UART1 logging of boot progress.
8	 *   A  FAL partition table parse -> locate "app", derive its logical address.
9	 *      App header validation (MSP / Reset Thumb / "BK7236\0\0" magic).
10	 * On success c_main prints "jump to:0x02010000\r\n", "JMP\r\n" and returns
11	 * the app logical vector address (e.g. 0x02010000). On failure it prints
12	 * "BAD\r\n" plus a short reason and loops forever (never returns).
13	 *
14	 * The app logical address equals FLASH_BASE + partition.offset, so the same
15	 * scan works if the table is later moved to a real flash partition.
16	 *
17	 * Freestanding: no libc, no mutable globals -> no .bss zeroing needed by
18	 * c_main (start.S calls c_main directly without a C runtime startup).
19	 */
20	
21	#include <stdint.h>
22	#include <stddef.h>
23	
24	#include "boot_wdt.h"
25	
26	extern void boot_clock_cold_init(void);
27	
28	/* ------------------------------------------------------------------ */
29	/* MMIO: BK7258 UART1 (matches the verified init in start.S).         */
30	/* ------------------------------------------------------------------ */
31	#define UART1_FIFO_ADDR   0x4583001Cu
32	#define UART1_STATUS_ADDR 0x45830018u
33	#define UART1_TX_READY    (1u << 20)   /* bit20: TX-FIFO-not-full (assumed) */
34	
35	#define REG32(addr)       (*(volatile uint32_t *)(addr))
36	#define UART1_FIFO        REG32(UART1_FIFO_ADDR)
37	#define UART1_STATUS      REG32(UART1_STATUS_ADDR)
38	
39	/* ------------------------------------------------------------------ */
40	/* FAL partition table (mirrors struct fal_partition from the BK SDK,  */
41	/* fal_def.h: magic_word/name[24]/flash_name[24]/offset/len/reserved, */
42	/* 64 bytes per entry). XIP-readable const in .rodata.                 */
43	/* ------------------------------------------------------------------ */
44	#define FAL_DEV_NAME_MAX  24
45	#define FAL_PART_MAGIC    0x45503130u   /* 'E','P','1','0' (fal_partition.c) */
46	
47	#define FLASH_BASE        0x02000000u
48	
49	struct fal_partition {
50	    uint32_t magic_word;
51	    char     name[FAL_DEV_NAME_MAX];
52	    char     flash_name[FAL_DEV_NAME_MAX];
53	    long     offset;        /* logical offset on flash device */
54	    size_t   len;
55	    uint32_t reserved;
56	};
57	
58	__attribute__((used))
59	const struct fal_partition fal_partition_table[] = {
60	    { FAL_PART_MAGIC, "bootloader", "beken_onchip_crc", 0x00000L, 0x10000L,  0u },
61	    { FAL_PART_MAGIC, "cp_app",     "beken_onchip_crc", 0x10000L, 0x158000L, 0u },
62	    { FAL_PART_MAGIC, "ap_app",     "beken_onchip_crc", 0x168000L, 0x124000L, 0u },
63	};
64	#define FAL_PART_COUNT  (sizeof(fal_partition_table) / sizeof(fal_partition_table[0]))
65	
66	/* ------------------------------------------------------------------ */
67	/* UART output (self-implemented; correct nibble order, no v>>32 UB).  */
68	/* ------------------------------------------------------------------ */
69	static void uart_putc(char c)
70	{
71	    /*
72	     * Poll bit20 (TX-FIFO-not-full). The poll is bounded: if the bit polarity
73	     * is ever inverted on silicon, we degrade gracefully to the same
74	     * write-through behavior the verified minimal bootloader used, rather
75	     * than hanging the boot.
76	     */
77	    for (int i = 0; i < 100000; i++) {
78	        if (UART1_STATUS & UART1_TX_READY) {
79	            break;
80	        }
81	    }
82	    UART1_FIFO = (uint32_t)(uint8_t)c;
83	}
84	
85	static void uart_puts(const char *s)
86	{
87	    while (*s) {
88	        uart_putc(*s++);
89	    }
90	}
91	
92	static void print_hex32(uint32_t v)
93	{
94	    static const char hex[] = "0123456789ABCDEF";
95	    int s;
96	    /* for(s=28; s>=0; s-=4): avoids the v>>32 undefined behaviour that the
97	       earlier probe fell into (top nibble got shifted into oblivion). */
98	    for (s = 28; s >= 0; s -= 4) {
99	        uart_putc(hex[(v >> s) & 0xFu]);
100	    }
101	}
102	
103	static void log_u32(const char *label, uint32_t value)
104	{
105	    uart_puts(label);
106	    uart_puts("0x");
107	    print_hex32(value);
108	    uart_puts("\r\n");
109	}
