111	/* ------------------------------------------------------------------ */
112	/* Partition scan + helpers.                                          */
113	/* ------------------------------------------------------------------ */
114	static int name_eq(const char *a, const char *b)
115	{
116	    int i;
117	    for (i = 0; i < FAL_DEV_NAME_MAX; i++) {
118	        if (a[i] != b[i]) {
119	            return 0;
120	        }
121	        if (a[i] == '\0') {
122	            return 1;
123	        }
124	    }
125	    return 1;   /* equal across the full FAL_DEV_NAME_MAX width */
126	}
127	
128	static const struct fal_partition *fal_find(const char *name)
129	{
130	    size_t i;
131	    for (i = 0; i < FAL_PART_COUNT; i++) {
132	        if (fal_partition_table[i].magic_word != FAL_PART_MAGIC) {
133	            continue;
134	        }
135	        if (name_eq(fal_partition_table[i].name, name)) {
136	            return &fal_partition_table[i];
137	        }
138	    }
139	    return (const struct fal_partition *)0;
140	}
141	
142	/* ------------------------------------------------------------------ */
143	/* App header validation (ported from bk7236_min_bl.S to C).          */
144	/* ------------------------------------------------------------------ */
145	static int validate_app(uint32_t app_vec)
146	{
147	    volatile uint32_t *vec   = (volatile uint32_t *)app_vec;
148	    volatile uint32_t *magic = (volatile uint32_t *)(app_vec + 0x100u);
149	    uint32_t msp  = vec[0];
150	    uint32_t rst  = vec[1];
151	
152	    /* MSP must land in SRAM [0x28000000 .. 0x280A0000]. */
153	    if (msp < 0x28000000u || msp > 0x280A0000u) {
154	        uart_puts("BAD\r\nmsp OOR\r\n");
155	        return 0;
156	    }
157	    /* Reset_Handler must have the Thumb bit set. */
158	    if ((rst & 1u) == 0u) {
159	        uart_puts("BAD\r\nreset no-thumb\r\n");
160	        return 0;
161	    }
162	    /* app magic @ app_vec + 0x100 == "BK7236\0\0"
163	       bytes  42 4B 37 32 -> word 0x32374B42
164	              33 36 00 00 -> word 0x00003633 */
165	    if (magic[0] != 0x32374B42u) {
166	        uart_puts("BAD\r\nmagic0\r\n");
167	        return 0;
168	    }
169	    if (magic[1] != 0x00003633u) {
170	        uart_puts("BAD\r\nmagic1\r\n");
171	        return 0;
172	    }
173	    return 1;
174	}
175	
176	/* ------------------------------------------------------------------ */
177	/* C entry called from start.S. Returns app logical vector address.   */
178	/* ------------------------------------------------------------------ */
179	__attribute__((used))
180	uint32_t c_main(void)
181	{
182	    const struct fal_partition *app;
183	    uint32_t app_vec;
184	    int cold_ok = 0;
185	    int retry;
186	
187	    uart_puts("u_bootloader enter\r\n");
188	
189	    /* --- WDT (product-grade): arm both APB + AON watchdogs (~8 s timeout).
190	     * Mirrors vendor bootloader sub_2000FE4: SYS_CTRL config + key unlock.
191	     * If boot_clock_cold_init or app validation hangs, WDT resets the chip.
192	     */
193	
194	    boot_wdt_init();
195	    boot_wdt_feed();
196	
197	    /* --- Cold-start DPLL enable + SPI recalibration.
198	     * On cold reset the BootROM leaves EN_DPLL=0; boot_clock_cold_init()
199	     * mirrors the Armino SDK sys_hal_early_init analog-register sequence.
200	     * If any analog-SPI write times out (ANA_SPI_TIMEOUT), the function
201	     * returns early and the app sees DPLL off.
202	     *
203	     * Retry up to 3 times: SPI timeouts can be transient (power-on noise).
204	     * Worst-case time: ~100 ms per attempt × 3 = 300 ms << 8 s WDT.
205	     */
206	
207	    for (retry = 0; retry < 3; retry++) {
208	        boot_wdt_feed();
209	        boot_clock_cold_init();
210	
211	        /* Check DPLL enable (ANA_REG5 bit5).  If set, cold-init succeeded. */
212	        if (REG32(0x44010114u) & (1u << 5)) {
213	            cold_ok = 1;
214	            break;
215	        }
216	
217	        uart_puts("BClk RETRY\r\n");
218	    }
219	
220	    boot_wdt_feed();
221	
222	    if (!cold_ok) {
223	        /* All retries exhausted: DPLL not enabled.  Do NOT jump to app
224	         * (app would see BootROM default state, DPLL off, DVFS would try
225	         * to switch to cksel=2 with DPLL off — undefined behavior).
226	         * Hang with WDT feed: the chip resets in ~8 s, giving a clean
227	         * retry window and leaving UART output visible for debugging. */
228	        uart_puts("BClk RETRY FAIL\r\n");
229	        for (;;) {
230	            boot_wdt_feed();
231	        }
232	    }
233	
234	    /* --- FAL partition parse -> find "app". */
235	
236	    boot_wdt_feed();
237	    app = fal_find("cp_app");
238	    if (app == (const struct fal_partition *)0) {
239	        uart_puts("BAD\r\nno app part\r\n");
240	        for (;;) {
241	            boot_wdt_feed();
242	        }
243	    }
244	    app_vec = FLASH_BASE + (uint32_t)app->offset;
245	    log_u32("partition app @ ", app_vec);
246	
247	    /* --- Validate app header. */
248	
249	    if (!validate_app(app_vec)) {
250	        for (;;) {
251	            boot_wdt_feed();
252	        }
253	    }
254	
255	    /* --- Feed WDT one last time before jumping to app.
256	     * The app's DVFS bring-up runs quickly (< 1 ms), but if it ever hangs
257	     * before the NuttX scheduler takes over WDT management, the hardware
258	     * WDT still fires. */
259	
260	    boot_wdt_feed();
261	    log_u32("jump to:", app_vec);
262	    uart_puts("JMP\r\n");
263	    return app_vec;
264	}
