93	static int ipc_heartbeat_timeout(void)
94	{
95		u32   cur_time;
96	
97		cur_time = (u32)rtos_get_time();
98	
99		if(cpu_x_state == CORE_POWER_OFF)
100		{
101			return 0;
102		}
103		if((cpu_x_state == CORE_STARTING) || (cpu_x_dump != 0))
104		{
105			cpu_x_heartbeat_timestamp = cur_time;
106			return 0;
107		}
108	
109		if(cur_time >= cpu_x_heartbeat_timestamp)
110		{
111			cur_time -= cpu_x_heartbeat_timestamp;
112		}
113		else
114		{
115			cur_time += (~(cpu_x_heartbeat_timestamp)) + 1;  // wrap around. 
116		}
117		
118		if(cur_time < CONFIG_INT_WDT_PERIOD_MS)
119		{
120			cpu_x_heartbeat_timestamp = (u32)rtos_get_time();
121			return 0;
122		}
123		if (bk_pm_module_lv_sleep_state_get(PM_DEV_ID_DEFAULT))
124		{
125			cpu_x_heartbeat_timestamp = (u32)rtos_get_time();
126			bk_pm_module_lv_sleep_state_clear(PM_DEV_ID_DEFAULT);
127			return 0;
128		}
129	
130		if(s_mb_ipc_work_state == MB_IPC_EXIT_LV)
131		{
132			cpu_x_heartbeat_timestamp = (u32)rtos_get_time();
133			s_mb_ipc_work_state = MB_IPC_WORKING;
134			return 0;
135		}
136	
137		return 1;
138	}
