198	static void mb_ipc_task( void *para )
199	{
200		bk_err_t	ret_val;
201		u32    events;
202		u32    check_time = BEKEN_WAIT_FOREVER;
203	
204		mb_ipc_init_lv_callback();
205	
206		ret_val = rtos_init_event_ex(&mb_ipc_heart_event);
207	
208		if(ret_val != BK_OK)
209		{
210			rtos_delete_thread(NULL);
211			return;
212		}
213	
214		while(1)
215		{
216			events = rtos_wait_event_ex(&mb_ipc_heart_event, MB_IPC_ALL_FLAGS, true, check_time);
217	
218			if(events == 0)
219			{
220				// timeout, so check heartbeat.
221				events = MB_IPC_HEARTBEAT_FLAG;
222			}
223	
224			if(events & MB_IPC_STOP_CORE_FLAG)  // process this event at first!!!!
225			{
226				if(cpu_x_state == CORE_POWER_OFF)
227				{
228					events = 0;  // clear all events.
229				}
230			}
231			
232			if(events & MB_IPC_START_CORE_FLAG)
233			{
234				u8   retry_cnt = 0;
235	
236				while(cpu_x_state == CORE_STARTING)
237				{
238					ipc_heartbeat_timeout();
239					
240					if(events & MB_IPC_POWER_UP_FLAG)
241					{
242						if(cpu_x_state == CORE_STARTING)
243						{
244							cpu_x_state = CORE_POWER_ON;
245							break;  // cpu1 power on. 
246						}
247					}
248					else
249					{
250						if( retry_cnt > 3)
251						{
252							BK_DUMP_OUT("IPC retry to start core%d, retry_cnt:%d\r\n", cpu_x_id, retry_cnt);
253							// restart_cpu_x();
254							break;
255						}
256						else
257						{
258							events = rtos_wait_event_ex(&mb_ipc_heart_event, MB_IPC_POWER_UP_FLAG, true, 2000);//2s
259						}
260					}
261	
262					retry_cnt++;
263				}
264	
265				// discard this event when not in CORE_STARTING state.
266			}
267			
268			if(events & MB_IPC_HEARTBEAT_FLAG)
269			{
270				if(ipc_heartbeat_timeout())
271				{
272					BK_LOGE(MOD_TAG, "IPC[%d]heartbeat timeout %d,%d\r\n",cpu_x_id,cpu_x_heartbeat_timestamp,(u32)rtos_get_time());
273					/*when cpu1 heartbeat timeout, then system reboot*/
274					cpu_x_heartbeat_timeout = 1;
275					BK_ASSERT(false);
276				}
277			}
278	
279			if(cpu_x_state == CORE_POWER_OFF)
280			{
281				check_time = BEKEN_WAIT_FOREVER;
282			}
283			else
284			{
285				check_time = CONFIG_INT_WDT_PERIOD_MS;
286			}
287		}
288	}
