17	#define TIMER0_REG_SET(reg_id, l, h, v) REG_SET((SOC_TIMER0_REG_BASE + ((reg_id) << 2)), (l), (h), (v))
18	#define TIMER0_PERIOD 0xFFFFFFFF
19	
20	static inline uint32_t timer_hal_get_timer0_cnt(void)
21	{
22		volatile uint32_t int_level = 0;
23		uint32_t cnt = 0;
24		int_level = rtos_enter_critical();
25		TIMER0_REG_SET(8, 2, 3, 0);
26		TIMER0_REG_SET(8, 0, 0, 1);
27		while (REG_READ((SOC_TIMER0_REG_BASE + (8 << 2))) & BIT(0));
28	
29		cnt = REG_READ(SOC_TIMER0_REG_BASE + (9 << 2));
30		rtos_exit_critical(int_level);
31		return cnt;
32	}
33	
34	static inline uint32_t timer_hal_diff(uint32_t begin, uint32_t end)
35	{
36		if (end > begin) {
37			return end - begin;
38		} else {
39			return (TIMER0_PERIOD - begin + end);
40		}
41	}
42	
43	void timer_hal_us_init(uint32_t us)
44	{
45		TIMER0_REG_SET(2, 0, 0, 1);
46		REG_WRITE((SOC_TIMER0_REG_BASE + (4 << 2)), TIMER0_PERIOD);
47		TIMER0_REG_SET(7, 0, 0, 1);
48		SYS_REG_SET(0xc, 4, 4, 1);
49		SYS_REG_SET(8, 20, 20, 1);
50	}
