52	/**
53	 * TODO optimize it!
54	 *
55	 * If we need very accurate delay, please write your owner delay!
56	 * 
57	 * Test Result:
58	 *  us          actual
59	 * --------------------------------
60	 *  1     |      8.8
61	 *  2     |      8.8
62	 *  3     |      8.4
63	 *  4     |      10
64	 *  5     |      9.6
65	 *  100   |      106
66	 *  1000  |      1007
67	 */
68	void timer_hal_delay_us(uint32_t us)
69	{
70		uint32_t delay_cycle = 26 * us;
71	
72		if ((REG_READ(SOC_TIMER0_REG_BASE + (7 << 2)) & BIT(0)) == 0) {
73			TIMER0_REG_SET(7, 0, 0, 1);
74		}
75	
76		uint32_t begin = timer_hal_get_timer0_cnt();
77		uint32_t end;
78		uint32_t diff;
79	
80		do {
81			end = timer_hal_get_timer0_cnt();
82			diff = timer_hal_diff(begin, end);
83		} while (diff < delay_cycle);
84	}
