547	uint64_t bk_timer_get_time(timer_id_t timer_id, uint32_t div, uint32_t last_count, timer_value_unit_t unit_type)
548	{
549	    TIMER_RETURN_ON_NOT_INIT();
550	    TIMER_RETURN_ON_INVALID_ID(timer_id);
551	
552	    TIMER_PM_CHECK_RESTORE(timer_id);
553	
554	    uint64_t current_time = 0;
555	    uint64_t unit_factor = 1;
556	
557	    uint64_t current_count = timer_hal_get_count(&s_timer.hal, timer_id) + last_count;
558	
559	    if (div == 0) {
560	        div = 1;
561	    }
562	
563	#if (CONFIG_SYSTEM_CTRL)
564		uint32_t group_index = 0;
565		uint32_t timer_clock = TIMER_SCLK_XTAL;
566	
567		group_index = timer_id / SOC_TIMER_CHAN_NUM_PER_GROUP;
568		switch(group_index)
569		{
570			case 0:
571				timer_clock = sys_hal_timer_select_clock_get(SYS_SEL_TIMER0);
572				break;
573			case 1:
574				timer_clock = sys_hal_timer_select_clock_get(SYS_SEL_TIMER1);
575				break;
576			default:
577				break;
578		}
579	
580	    unit_factor = (unit_type == TIMER_UNIT_MS) ? 1 : 1000;
581	
582		if(timer_clock == TIMER_SCLK_XTAL) {
583	        current_time = unit_factor * current_count * (uint64_t)div / TIMER_CLOCK_FREQ_26M;
584		} else {
585	        current_time = unit_factor * current_count * (uint64_t)div / TIMER_CLOCK_FREQ_32K;
586		}
587	
588	#else
589	    if (timer_id < SOC_TIMER_CHAN_NUM_PER_GROUP) {
590	        current_time = unit_factor * current_count * div / TIMER_CLOCK_FREQ_26M;
591	    } else {
592	        current_time = unit_factor * current_count * div / TIMER_CLOCK_FREQ_32K;
593	    }
594	#endif
595	
596	    return current_time;
597	}
