605	    TIMER_RETURN_TIMER_ID_IS_ERR(timer_id);
606	#endif
607	    uint64_t current_count = 0;
608	    uint64_t delta_count = 0;
609	    uint64_t end_count = 0;
610	
611	    TIMER_PM_CHECK_RESTORE(timer_id);
612	
613	    timer_chan_init_common(timer_id);
614	    timer_chan_enable_interrupt_common(timer_id);
615	
