617	    delta_count = timer_hal_cal_end_count(timer_id, time_us, 1, TIMER_UNIT_US);
618	    end_count = current_count + delta_count;
619	
620	    if(end_count > 0xFFFFFFFFFFFFFFFF){
621	        end_count = 0xFFFFFFFFFFFFFFFF;
622	    }
623	
624	    timer_ll_set_end_count(s_timer.hal.hw, timer_id, (uint32_t)end_count);
625	    timer_ll_set_clk_div(s_timer.hal.hw, timer_id, 0);
626	    timer_ll_clear_chan_interrupt_status(s_timer.hal.hw, timer_id);
627	
628	    timer_hal_start_common(&s_timer.hal, timer_id);
