100	static int bk7258_sdk_irq_dispatch(int irq, void *context, void *arg)
101	{
102	  unsigned int source;
103	  int_group_isr_t handler;
104	
105	  (void)context;
106	  (void)arg;
107	
108	  source = (unsigned int)(irq - BK7258_SDK_IRQ_FIRST);
109	  if (source >= BK7258_SDK_IRQ_COUNT)
110	    {
111	      return OK;
112	    }
113	
114	  handler = g_bk7258_sdk_irq_handlers[source];
115	  if (handler != NULL)
116	    {
117	      handler();
118	    }
119	
120	  return OK;
121	}
