124	bk7258_sdk_irq_unregister_locked(unsigned int index, int irq)
125	{
126	  int ret;
127	
128	  up_disable_irq(irq);
129	  bk7258_clear_pending_irq(irq);
130	  g_bk7258_sdk_irq_handlers[index] = NULL;
131	  UP_DSB();
132	  UP_ISB();
133	
