141	
142	bk_err_t bk_int_isr_register(icu_int_src_t source,
143	                             int_group_isr_t handler, void *arg)
144	{
145	  unsigned int index = (unsigned int)source;
146	  int priority;
147	  int irq;
148	  int ret;
149	
150	  (void)arg; /* The CP CM33 SDK implementation also ignores this argument. */
151	
152	  irq = bk7258_sdk_source_to_irq(source);
153	  if (irq < 0)
154	    {
155	      return BK_ERR_INT_DEVICE_NONE;
156	    }
157	
158	  priority = bk7258_sdk_irq_encode_priority(
159	      bk7258_sdk_irq_default_priority(source));
160	
161	  /* Registration replaces the previous owner of this source.  Keep the line
162	   * disabled and non-pending until both NuttX dispatch state and priority are
163	   * complete.
164	   */
165	
166	  up_disable_irq(irq);
167	  bk7258_clear_pending_irq(irq);
168	  g_bk7258_sdk_irq_handlers[index] = NULL;
169	
170	  ret = irq_detach(irq);
171	  if (ret < 0)
172	    {
173	      return BK_FAIL;
174	    }
175	
176	  ret = up_prioritize_irq(irq, priority);
177	  if (ret < 0)
178	    {
179	      return BK_FAIL;
180	    }
181	
182	  /* A NULL SDK callback has the same net effect as the vendor CM33 path:
183	   * the previous callback is removed and the interrupt stays disabled.
184	   */
185	
186	  if (handler == NULL)
187	    {
188	      return BK_OK;
189	    }
190	
191	  ret = irq_attach(irq, bk7258_sdk_irq_dispatch, NULL);
192	  if (ret < 0)
193	    {
194	      return BK_FAIL;
195	    }
196	
197	  g_bk7258_sdk_irq_handlers[index] = handler;
198	  UP_DSB();
199	  UP_ISB();
200	  up_enable_irq(irq);
201	
202	  return BK_OK;
203	}
