205	bk_err_t bk_int_isr_unregister(icu_int_src_t source)
206	{
207	  unsigned int index = (unsigned int)source;
208	  int irq;
209	  int ret;
210	
211	  irq = bk7258_sdk_source_to_irq(source);
212	  if (irq < 0)
213	    {
214	      return BK_ERR_INT_DEVICE_NONE;
215	    }
216	
217	  up_disable_irq(irq);
218	  bk7258_clear_pending_irq(irq);
219	  g_bk7258_sdk_irq_handlers[index] = NULL;
220	  UP_DSB();
221	  UP_ISB();
222	
223	  ret = irq_detach(irq);
224	  return ret < 0 ? BK_FAIL : BK_OK;
225	}
226	
227	bk_err_t bk_int_set_priority(icu_int_src_t source, uint32_t priority)
228	{
229	  int encoded;
230	  int irq;
231	
232	  irq = bk7258_sdk_source_to_irq(source);
233	  if (irq < 0)
234	    {
235	      return BK_ERR_INT_DEVICE_NONE;
236	    }
237	
238	  encoded = bk7258_sdk_irq_encode_priority(priority);
239	  if (encoded < 0)
240	    {
241	      return BK_ERR_NOT_SUPPORT;
242	    }
243	
244	  return up_prioritize_irq(irq, encoded) < 0 ? BK_FAIL : BK_OK;
245	}
246	
247	void interrupt_init(void)
248	{
249	  /* NuttX up_irqinitialize() already owns VTOR, g_irqvector, and the NVIC. */
250	}
251	
252	void interrupt_deinit(void)
253	{
254	  unsigned int source;
255	
256	  for (source = 0; source < BK7258_SDK_IRQ_COUNT; source++)
257	    {
258	      if (g_bk7258_sdk_irq_handlers[source] != NULL)
259	        {
260	          bk_int_isr_unregister((icu_int_src_t)source);
261	        }
262	    }
263	}
