89	__IRAM_SEC static void wdt_init_common(void)
90	{
91	#if (CONFIG_SYSTEM_CTRL)
92		sys_drv_dev_clk_pwr_up(CLK_PWR_ID_WDG_CPU, CLK_PWR_CTRL_PWR_UP);
93	#else
94		power_up_wdt();
95	#endif
96	}
97	
98	__attribute__((section(".itcm_sec_code"))) static void wdt_deinit_common(void)
99	{
100		s_wdt_period = CONFIG_INT_WDT_PERIOD_MS;
101		wdt_hal_reset_config_to_default(&s_wdt.hal);
102	#if (CONFIG_SYSTEM_CTRL)
103		close_wdt();
104		//sys_drv_dev_clk_pwr_up(CLK_PWR_ID_WDG_CPU, CLK_PWR_CTRL_PWR_DOWN);
105	#else
106		power_down_wdt();
107	#endif
108	}
