110	bk_err_t bk_wdt_driver_init(void)
111	{
112		if (s_wdt_driver_is_init) {
113			return BK_OK;
114		}
115	
116		os_memset(&s_wdt, 0, sizeof(s_wdt));
117		wdt_hal_init(&s_wdt.hal);
118	
119		bk_timer_start(TIMER_ID2, WDT_BARK_TIME_MS, (timer_isr_t)bk_wdt_feed_handle);
120		sys_drv_nmi_wdt_set_clk_div(NMI_WDT_CLK_DIV_16);
121		aon_pmu_drv_wdt_rst_dev_enable();
122	
123		s_wdt_driver_is_init = true;
124	
125		return BK_OK;
126	}
127	
128	bk_err_t bk_wdt_driver_deinit(void)
129	{
130		if (!s_wdt_driver_is_init) {
131			return BK_OK;
132		}
133		wdt_deinit_common();
134	
135		bk_timer_stop(TIMER_ID2);
136	
137		s_wdt_driver_is_init = false;
138	
139		return BK_OK;
140	}
