142	/* 1. power up wdt
143	 * 2. set period
144	 */
145	__IRAM_SEC bk_err_t bk_wdt_start(uint32_t timeout_ms)
146	{
147		WDT_RETURN_ON_DRIVER_NOT_INIT();
148		WDT_RETURN_ON_INVALID_PERIOD(timeout_ms);
149	
150		if (!timeout_ms) {
151			timeout_ms = CONFIG_INT_WDT_PERIOD_MS;
152		}
153	
154		s_wdt_period = timeout_ms;
155		wdt_init_common();
156		wdt_hal_init_wdt(&s_wdt.hal, timeout_ms);
157		s_wdt.init_bits |= BIT(0);
158		WDT_LOGV("bk_wdt_start, s_wdt.init_bits:%x\n", s_wdt.init_bits);
159	
160		return BK_OK;
161	}
162	
163	__attribute__((section(".itcm_sec_code"))) bk_err_t bk_wdt_stop(void)
164	{
165		WDT_RETURN_ON_DRIVER_NOT_INIT();
166		wdt_deinit_common();
167		s_wdt.init_bits &= ~BIT(0);
168		//WDT_LOGV("bk_wdt_stop, s_wdt.init_bits:%x\n", s_wdt.init_bits);
169		return BK_OK;
170	}
