183	void bk_int_wdt_feed(void)
184	{
185		static uint64_t s_last_int_wdt_feed_tick = 0;
186		uint64_t current_tick = GET_TASK_CURRENT_TICK();
187	
188		if ((current_tick - s_last_int_wdt_feed_tick) >= s_feed_watchdog_time) {
189			bk_wdt_feed();
190			s_last_int_wdt_feed_tick = current_tick;
191			//WDT_LOGV("feed interrupt watchdog, s_feed_watchdog_time = %u ms.\n", s_feed_watchdog_time);
192		}
193	}
