223	void bk_task_wdt_timeout_check(void)
224	{
225		if (s_last_task_wdt_feed_tick && s_task_wdt_enabled) {
226			const uint64_t c_last_feed_tick = s_last_task_wdt_feed_tick;
227			const uint64_t current_tick = GET_TASK_CURRENT_TICK();
228	
229			if(current_tick > c_last_feed_tick) {
230				if ((current_tick - c_last_feed_tick) > TASK_WDG_PERIOD_TICK) {
231					if ((current_tick - s_last_task_wdt_log_tick) > TASK_WDG_PERIOD_TICK) {
232						WDT_LOGW("task watchdog triggered\r\n");
233						s_last_task_wdt_log_tick = current_tick;
234						BK_ASSERT(0);
235					}
236				}
237			}
238		}
239	}
240	
241	#endif
