471	static void flash_server_task(void * param)
472	{
473		u32  handle;
474		u32  connect_handle;
475	
476		if(rtos_init_event_ex(&flash_svr_event) != BK_OK)
477		{
478			rtos_delete_thread(NULL);
479			return;
480		}
481	
482		handle = mb_ipc_socket(IPC_GET_ID_PORT(FLASH_SERVER), flash_svr_rx_callback);
483	
484		if(handle == 0)
485		{
486			TRACE_E("ipc_svr", "create_socket failed.\r\n");
487	
488			rtos_deinit_event_ex(&flash_svr_event);
489			rtos_delete_thread(NULL);
490	
491			return ;
492		}
493	
494		s_flash_svr_init = 2;
495	
496		while(1)
497		{
498			u32 event = rtos_wait_event_ex(&flash_svr_event, FLASH_SVR_EVENTS, 1, BEKEN_WAIT_FOREVER);
499	
500			if(event == 0)  // timeout.
501			{
502				continue;
503			}
504	
505			if(event & FLASH_SVR_QUIT_EVENT)
506			{
507				break;
508			}
509	
510			for(int i = 0; i < FLASH_SVR_CONNECT_MAX; i++)
511			{
512				if(event & (0x01 << i))
513				{
514					connect_handle = mb_ipc_server_get_connect_handle(handle, i);
515					flash_svr_connect_handler(connect_handle, i);
516				}
517			}
518		}
519	
520		mb_ipc_server_close(handle, FLASH_SVR_WAIT_TIME);
521	
522		rtos_deinit_event_ex(&flash_svr_event);
523	
524		s_flash_svr_init = 0;
525	
526		rtos_delete_thread(NULL);
527	}
