56	static inline void timer_ll_init(timer_hw_t *hw, uint32_t chan)
57	{
58	#if CONFIG_TIMER_SUPPORT_ID_BITS
59	    if ((~CONFIG_TIMER_SUPPORT_ID_BITS) & BIT(chan)) {
60	        return;
61	    }
62	#endif
63	
64	    uint32_t group = TIMER_LL_GROUP(chan);
65	    uint32_t group_chan = TIMER_LL_CHAN(chan);
66	
67	    if (TIMER_GROUP_CHAN0 == group_chan) {
68	        hw->group[group].ctrl.timer0_en = 0;
69	        hw->group[group].ctrl.timer0_int_en = 0;
70	    } else if (TIMER_GROUP_CHAN1 == group_chan) {
71	        hw->group[group].ctrl.timer1_en = 0;
72	        hw->group[group].ctrl.timer1_int_en = 0;
73	    } else {
74	        hw->group[group].ctrl.timer2_en = 0;
75	        hw->group[group].ctrl.timer2_int_en = 0;
76	    }
77	
78		hw->group[group].read_ctrl.v = 0;
79		hw->group[group].timer_read_value = 0;
80		timer_ll_soft_reset(hw, group);
