606	
607	int up_timer_gettime(struct timespec *ts)
608	{
609	  uint64_t usec;
610	  uint32_t counter;
611	  uint32_t verify;
612	  uint32_t overflow;
613	  uint32_t sec;
614	  int pending;
615	  irqstate_t flags;
616	
617	  DEBUGASSERT(ts);
618	
619	  /* Timer not initialized yet, return zero */
620	
621	  if (g_tickless.tch == 0)
622	    {
623	      ts->tv_nsec = 0;
624	      ts->tv_sec  = 0;
625	      return OK;
626	    }
627	
628	  /* Temporarily disable the overflow counter.  NOTE that we have to be
629	   * careful here because  stm32_tc_getpending() will reset the pending
630	   * interrupt status.  If we do not handle the overflow here then, it will
631	   * be lost.
632	   */
633	
634	  flags    = enter_critical_section();
635	
636	  overflow = g_tickless.overflow;
637	  counter  = STM32_TIM_GETCOUNTER(g_tickless.tch);
638	  pending  = STM32_TIM_CHECKINT(g_tickless.tch, GTIM_SR_UIF);
639	  verify   = STM32_TIM_GETCOUNTER(g_tickless.tch);
640	
641	  /* If an interrupt was pending before we re-enabled interrupts,
642	   * then the overflow needs to be incremented.
643	   */
644	
645	  if (pending)
646	    {
647	      STM32_TIM_ACKINT(g_tickless.tch, GTIM_SR_UIF);
648	
649	      /* Increment the overflow count and use the value of the
650	       * guaranteed to be AFTER the overflow occurred.
651	       */
652	
653	      overflow++;
654	      counter = verify;
655	
656	      /* Update tickless overflow counter. */
657	
658	      g_tickless.overflow = overflow;
659	    }
660	
661	  leave_critical_section(flags);
662	
663	  tmrinfo("counter=%lu (%lu) overflow=%lu, pending=%i\n",
664	         (unsigned long)counter,  (unsigned long)verify,
665	         (unsigned long)overflow, pending);
666	  tmrinfo("frequency=%lu\n", g_tickless.frequency);
667	
668	  /* Convert the whole thing to units of microseconds.
669	   *
670	   *   frequency = ticks / second
671	   *   seconds   = ticks * frequency
672	   *   usecs     = (ticks * USEC_PER_SEC) / frequency;
673	   */
674	#ifdef HAVE_32BIT_TICKLESS
675	  usec = ((((uint64_t)overflow << 32) + (uint64_t)counter) * USEC_PER_SEC) /
676	         g_tickless.frequency;
677	#else
678	  usec = ((((uint64_t)overflow << 16) + (uint64_t)counter) * USEC_PER_SEC) /
679	         g_tickless.frequency;
680	#endif
681	
682	  /* And return the value of the timer */
683	
684	  sec         = (uint32_t)(usec / USEC_PER_SEC);
685	  ts->tv_sec  = sec;
686	  ts->tv_nsec = (usec - (sec * USEC_PER_SEC)) * NSEC_PER_USEC;
687	
688	  tmrinfo("usec=%llu ts=(%lu, %lu)\n",
689	          usec, (unsigned long)ts->tv_sec, (unsigned long)ts->tv_nsec);
690	
691	  return OK;
692	}
